export class PaddleController {
  private paddle: HTMLCanvasElement;
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private game: HTMLDivElement;
  private ball: HTMLCanvasElement;
  private ballCtx: CanvasRenderingContext2D;
  private paddleSpeed: number = 5;
  private ballSpeedX: number = 4;
  private ballSpeedY: number = 4;
  private ballRadius: number = 10;
  private score: number = 0;
  private isGameRunning: boolean = true;
  private lastTime: number = 0;

  constructor() {
    this.canvas = document.createElement('canvas');
    this.canvas.width = 800;
    this.canvas.height = 600;
    this.ctx = this.canvas.getContext('2d');
    this.game = document.createElement('div');
    this.game.style.width = '800px';
    this.game.style.height = '600px';
    this.game.appendChild(this.canvas);
    this.paddle = document.createElement('canvas');
    this.paddle.width = 10;
    this.paddle.height = 100;
    this.paddleCtx = this.paddle.getContext('2d');
    this.ball = document.createElement('canvas');
    this.ball.width = this.ball.height = this.ballRadius * 2;
    this.ballCtx = this.ball.getContext('2d');
    this.game.appendChild(this.paddle);
    this.game.appendChild(this.ball);
    document.body.appendChild(this.game);
    this.init();
  }

  private init() {
    this.ctx.fillStyle = '#000';
    this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
    this.paddleCtx.fillStyle = '#f00';
    this.paddleCtx.fillRect(0, 0, this.paddle.width, this.paddle.height);
    this.ballCtx.fillStyle = '#0f0';
    this.ballCtx.beginPath();
    this.ballCtx.arc(this.ballRadius, this.ballRadius, this.ballRadius, 0, Math.PI * 2);
    this.ballCtx.fill();
    this.update();
  }

  private update() {
    if (!this.isGameRunning) return;
    this.lastTime = Date.now();
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.paddleCtx.clearRect(0, 0, this.paddle.width, this.paddle.height);
    this.ballCtx.clearRect(0, 0, this.ball.width, this.ball.height);
    this.updatePaddle();
    this.updateBall();
    this.render();
    requestAnimationFrame(this.update.bind(this));
  }

  private updatePaddle() {
    const rect = this.paddle.getBoundingClientRect();
    const gameRect = this.game.getBoundingClientRect();
    const gameX = gameRect.left + this.game.offsetLeft;
    const gameY = gameRect.top + this.game.offsetTop;
    const paddleX = (event.clientX - gameX) - (this.paddle.width / 2);
    const paddleY = gameY + gameRect.height - this.paddle.height;
    this.paddle.style.left = paddleX + 'px';
    this.paddle.style.top = paddleY + 'px';
    this.paddleCtx.clearRect(0, 0, this.paddle.width, this.paddle.height);
    this.paddleCtx.fillStyle = '#f00';
    this.paddleCtx.fillRect(0, 0, this.paddle.width, this.paddle.height);
  }

  private updateBall() {
    const ballRect = this.ball.getBoundingClientRect();
    const ballX = ballRect.left + this.ball.width / 2;
    const ballY = ballRect.top + this.ball.height / 2;
    this.ballCtx.clearRect(0, 0, this.ball.width, this.ball.height);
    this.ballCtx.fillStyle = '#0f0';
    this.ballCtx.beginPath();
    this.ballCtx.arc(ballX, ballY, this.ballRadius, 0, Math.PI * 2);
    this.ballCtx.fill();
    this.ballSpeedX += (event.clientX - (ballX)) * 0.01;
    this.ballSpeedY += 0.1;
    const ballXNew = ballX + this.ballSpeedX;
    const ballYNew = ballY + this.ballSpeedY;
    if (ballYNew + this.ballRadius > this.canvas.height) {
      this.ballSpeedY = -this.ballSpeedY * 0.9;
      this.ballSpeedX *= 0.9;
    }
    if (ballXNew - this.ballRadius < 0 || ballXNew + this.ballRadius > this.canvas.width) {
      this.ballSpeedX = -this.ballSpeedX * 0.9;
    }
    if (ballYNew - this.ballRadius < 0) {
      this.ballSpeedY = -this.ballSpeedY;
    }
    if (ballYNew + this.ballRadius > this.paddle.getBoundingClientRect().top && ballXNew > this.paddle.getBoundingClientRect().left && ballXNew < this.paddle.getBoundingClientRect().right) {
      this.ballSpeedY = -this.ballSpeedY * 0.9;
      this.score++;
    }
    this.ballCtx.clearRect(0, 0, this.ball.width, this.ball.height);
    this.ballCtx.fillStyle = '#0f0';
    this.ballCtx.beginPath();
    this.ballCtx.arc(ballXNew, ballYNew, this.ballRadius, 0, Math.PI * 2);
    this.ballCtx.fill();
  }

  private render() {
    this.ctx.fillStyle = '#000';
    this.ctx.font = '20px Arial';
    this.ctx.fillText('Score: ' + this.score, 10, 30);
  }

  private startGame() {
    this.isGameRunning = true;
  }

  private stopGame() {
    this.isGameRunning = false;
  }

  private resetGame() {
    this.score = 0;
    this.isGameRunning = false;
  }
}

