export class PhysicsEngine {
  private paddleController: PaddleController;
  private ballSpeedX: number;
  private ballSpeedY: number;
  private ballRadius: number;
  private ballX: number;
  private ballY: number;
  private paddleY: number;
  private score: number;

  constructor(paddleController: PaddleController) {
    this.paddleController = paddleController;
    this.ballSpeedX = 4;
    this.ballSpeedY = 4;
    this.ballRadius = 10;
    this.ballX = 400;
    this.ballY = 300;
    this.paddleY = 550;
    this.score = 0;
  }

  update() {
    this.ballX += this.ballSpeedX;
    this.ballY += this.ballSpeedY;

    // Check for wall collision
    if (this.ballX <= 0 || this.ballX >= 790) {
      this.ballSpeedX = -this.ballSpeedX;
    }

    // Check for paddle collision
    if (this.ballY + this.ballRadius >= 550 && this.ballX >= this.paddleY && this.ballX <= this.paddleY + 100) {
      this.ballSpeedY = -this.ballSpeedY;
    }

    // Check for top wall collision
    if (this.ballY <= 0) {
      this.ballSpeedY = -this.ballSpeedY;
    }

    // Check for goal
    if (this.ballY + this.ballRadius >= 600) {
      this.score++;
      this.ballX = 400;
      this.ballY = 300;
      this.ballSpeedX = 4;
      this.ballSpeedY = 4;
    }

    this.paddleY = this.paddleController.getMoves()[0].dy;
    this.paddleController.updateCanvas();
  }

  getScore() {
    return this.score;
  }
}

