export class AIOpponent {
  private paddleController: PaddleController;
  private ballSpeedX: number;
  private ballSpeedY: number;
  private ballRadius: number;
  private ballX: number;
  private ballY: number;
  private paddleY: number;
  private score: number;

  constructor(paddleController: PaddleController) {
    this.paddleController = paddleController;
    this.ballSpeedX = 4;
    this.ballSpeedY = 4;
    this.ballRadius = 10;
    this.ballX = 400;
    this.ballY = 300;
    this.paddleY = 550;
    this.score = 0;
  }

  getMoves(): { x: number; y: number; }[] {
    const input = this.paddleController.getGameBoard().getCurrentPlayerInput();
    if (input === 'up') {
      return [{ x: 0, y: -1 }];
    } else if (input === 'down') {
      return [{ x: 0, y: 1 }];
    } else {
      return [];
    }
  }

  update() {
    const moves = this.getMoves();
    for (const move of moves) {
      move.dy += -9.81 * 0.1;
      move.dy *= 0.95;
      const paddle = this.paddleController.getGameBoard().getCurrentPlayer();
      if (paddle && paddle.isInPlay() && move.x > paddle.getXMin() && move.x < paddle.getXMax()) {
        move.dy *= -1;
      }
      if (move.x > this.paddleController.getGameBoard().getWidth()) {
        move.dx *= -0.5;
      } else if (move.x < 0) {
        move.dx *= -0.5;
      }
    }
    this.paddleController.updateCanvas();
  }
}

