export class GameRenderer {
  private canvas: HTMLCanvasElement;
  private paddleController: PaddleController;
  private ctx: CanvasRenderingContext2D;
  private ball: { x: number; y: number; vx: number; vy: number; radius: number };
  private paddle1: { x: number; y: number; width: number; height: number; vy: number };
  private paddle2: { x: number; y: number; width: number; height: number; vy: number };
  private score1: number;
  private score2: number;
  private speed: number;

  constructor(canvas: HTMLCanvasElement, paddleController: PaddleController) {
    this.canvas = canvas;
    this.paddleController = paddleController;
    this.ctx = this.canvas.getContext('2d')!;
    this.ball = { x: this.canvas.width / 2, y: this.canvas.height / 2, vx: 0, vy: 0, radius: 10 };
    this.paddle1 = { x: 20, y: this.canvas.height / 2 - 40, width: 10, height: 80, vy: 0 };
    this.paddle2 = { x: this.canvas.width - 30, y: this.canvas.height / 2 - 40, width: 10, height: 80, vy: 0 };
    this.score1 = 0;
    this.score2 = 0;
    this.speed = 3;
  }

  public init(): void {
    this.canvas.width = 800;
    this.canvas.height = 600;
    this.render();
    this.animate();
  }

  public render(): void {
    this.ctx.fillStyle = 'black';
    this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

    this.ctx.beginPath();
    this.ctx.arc(this.ball.x, this.ball.y, this.ball.radius, 0, Math.PI * 2);
    this.ctx.fillStyle = '#0095dd';
    this.ctx.fill();

    this.ctx.beginPath();
    this.ctx.moveTo(this.paddle1.x, this.paddle1.y);
    this.ctx.lineTo(this.paddle1.x + this.paddle1.width, this.paddle1.y);
    this.ctx.fillStyle = '#ffffff';
    this.ctx.fill();

    this.ctx.beginPath();
    this.ctx.moveTo(this.paddle2.x, this.paddle2.y);
    this.ctx.lineTo(this.paddle2.x + this.paddle2.width, this.paddle2.y);
    this.ctx.fillStyle = '#ffffff';
    this.ctx.fill();

    this.ctx.font = '24px Arial';
    this.ctx.fillText(this.score1, this.canvas.width / 4, 30);
    this.ctx.fillText(this.score2, this.canvas.width * 3 / 4, 30);
  }

  public animate(): void {
    this.update();
    this.render();
    requestAnimationFrame(this.animate.bind(this));
  }

  public update(): void {
    this.ball.x += this.ball.vx;
    this.ball.y += this.ball.vy;

    if (this.ball.x + this.ball.radius > this.canvas.width || this.ball.x - this.ball.radius < 0) {
      this.ball.vx = -this.ball.vx;
    }

    if (this.ball.y + this.ball.radius > this.canvas.height || this.ball.y - this.ball.radius < 0) {
      this.ball.vy = -this.ball.vy;
    }

    const paddle1Rect = { x: this.paddle1.x, y: this.paddle1.y, width: this.paddle1.width, height: this.paddle1.height };
    const paddle2Rect = { x: this.paddle2.x, y: this.paddle2.y, width: this.paddle2.width, height: this.paddle2.height };

    if (this.ball.x + this.ball.radius > this.paddle2.x && this.ball.y > this.paddle2.y && this.ball.y < this.paddle2.y + this.paddle2.height) {
      this.ball.vx = this.speed;
      this.ball.x = this.paddle2.x + this.paddle2.width;
      this.ball.vx = -this.ball.vx;
    }

    if (this.ball.x - this.ball.radius < this.paddle1.x + this.paddle1.width && this.ball.y > this.paddle1.y && this.ball.y < this.paddle1.y + this.paddle1.height) {
      this.ball.vx = this.speed;
      this.ball.x = this.paddle1.x + this.paddle1.width;
      this.ball.vx = -this.ball.vx;
    }

    if (this.ball.x > this.canvas.width) {
      this.score1++;
      this.ball.x = this.canvas.width / 2;
      this.ball.y = this.canvas.height / 2;
      this.ball.vx = 0;
      this.ball.vy = 0;
    }

    if (this.ball.x < 0) {
      this.score2++;
      this.ball.x = this.canvas.width / 2;
      this.ball.y = this.canvas.height / 2;
      this.ball.vx = 0;
      this.ball.vy = 0;
    }

    this.paddle1.y += this.paddle1.vy;
    this.paddle2.y += this.paddle2.vy;

    if (this.paddle1.y < 0) {
      this.paddle1.y = 0;
    }

    if (this.paddle1.y + this.paddle1.height > this.canvas.height) {
      this.paddle1.y = this.canvas.height - this.paddle1.height;
    }

    if (this.paddle2.y < 0) {
      this.paddle2.y = 0;
    }

    if (this.paddle2.y + this.paddle2.height > this.canvas.height) {
      this.paddle2.y = this.canvas.height - this.paddle2.height;
    }
  }
}
